    uint32_t n;

    x = lv_obj_get_style_x(obj, LV_PART_MAIN);
    y = lv_obj_get_style_y(obj, LV_PART_MAIN);
    w = lv_obj_get_style_width(obj, LV_PART_MAIN);
    h = lv_obj_get_style_height(obj, LV_PART_MAIN);

    if (ui_coord_is_px(x)) {
        lv_obj_set_x(obj, ui_px(x));
    }
    if (ui_coord_is_px(y)) {
        /* 只有直接挂在屏幕上的控件加垂直居中。子控件的 y 相对父控件。 */
        lv_obj_set_y(obj, (dashboard && on_screen) ? ui_sy(y) : (dashboard ? ui_py(y) : ui_fill_y(y)));
    }
    if (ui_coord_is_px(w) && w > 0) {
        lv_obj_set_width(obj, ui_px(w));
    }
    if (ui_coord_is_px(h) && h > 0) {
        lv_obj_set_height(obj, dashboard ? ui_py(h) : ui_fill_y(h));
    }

    if (dashboard && lv_obj_check_type(obj, &lv_arc_class)) {
        int32_t aw = lv_obj_get_style_arc_width(obj, LV_PART_MAIN);
        int32_t iw = lv_obj_get_style_arc_width(obj, LV_PART_INDICATOR);

        if (aw > 0)
            lv_obj_set_style_arc_width(obj, ui_px(aw), LV_PART_MAIN);
        if (iw > 0)
            lv_obj_set_style_arc_width(obj, ui_px(iw), LV_PART_INDICATOR);
    }

    /* lv_image_class 的子类（含 lv_animimg、lv_aic_player）也算。
       照片页横纵比例不同，把图拉进 360x360。仪表盘横纵同一个比例，圆不会变成椭圆。 */
    if (lv_obj_has_class(obj, &lv_image_class)) {
        lv_image_t *img = (lv_image_t *)obj;

        box_w = lv_obj_get_style_width(obj, LV_PART_MAIN);
        box_h = lv_obj_get_style_height(obj, LV_PART_MAIN);
        if (!ui_coord_is_px(box_w) || box_w <= 0)
            box_w = dashboard ? img->w : ui_px(img->w);
        if (!ui_coord_is_px(box_h) || box_h <= 0)
            box_h = dashboard ? img->h : ui_fill_y(img->h);
        ui_stretch_image(obj, img->w, img->h, box_w, box_h);
    }

    n = lv_obj_get_child_count(obj);
    for (i = 0; i < n; i++) {
        ui_fit_obj(lv_obj_get_child(obj, i), dashboard, false);
    }
